/**
 * config → manifest.json. §5 step 5.
 *
 * Pure and dependency-free so both the CLI (Node) and any test can call it. The
 * OUTPUT is validated by the platform's own zod schema
 * (frontend/src/server/templates/cptf-manifest.ts) — this function does not
 * re-implement that validation, it only performs the shape transform. Keeping
 * the two separate is deliberate: the schema is the authority, and if this
 * emitter drifts, the schema catches it rather than both being wrong together.
 *
 * The transform is mostly record → array, lifting each key into an `id` field.
 * The author writes keyed records (a duplicate id is unwritable, §14.19); the
 * manifest stores arrays because it needs stable ORDER for the editor's section
 * and field ordering.
 */

import { collectLayers, type CollectedLayer } from "./collect-layers";
import type { TemplateConfig } from "./types";

/** Externals the platform provides at runtime. Pinned by the platform, not the
 *  author — §3.1 marks these as platform-owned, and the validator checks the set
 *  against CPTF_ALLOWED_EXTERNALS. */
export const PLATFORM_EXTERNALS: Record<string, string> = {
  react: "19.x",
  "react-dom": "19.x",
  "framer-motion": "12.x",
  "lucide-react": "0.4x",
};

export const SDK_RANGE = "^1.0.0";

export type BuildManifestOptions = {
  /** Overrides config.version. The CLI passes the CLI/package.json version. */
  version?: string;
  author?:
    | { kind: "first_party" }
    | { kind: "creator"; creatorId: string };
  suggestedInr?: number;
  ssr?: boolean;
};

export type BuildManifestResult = {
  manifest: Record<string, unknown>;
  warnings: string[];
};

export function buildManifest(
  config: TemplateConfig,
  options: BuildManifestOptions = {},
): Record<string, unknown> {
  return buildManifestWithWarnings(config, options).manifest;
}

/** As buildManifest, but also surfaces layer-collection warnings for the CLI. */
export function buildManifestWithWarnings(
  config: TemplateConfig,
  options: BuildManifestOptions = {},
): BuildManifestResult {
  const surfaces = Object.entries(config.surfaces ?? {}).map(([id, s]) => ({
    id,
    label: s.label,
    aspect: s.aspect,
  }));

  // Render once, structurally, to lift the inline <Layer> declarations out. This
  // never mounts React — collectLayers walks props.children — so a template that
  // would throw without real content still yields its layers.
  let layers: CollectedLayer[] = [];
  const warnings: string[] = [];
  try {
    const collected = collectLayers(config.render());
    layers = collected.layers;
    warnings.push(...collected.warnings);
  } catch (error) {
    warnings.push(
      `could not collect layers from render(): ${
        error instanceof Error ? error.message : String(error)
      }`,
    );
  }

  const manifest: Record<string, unknown> = {
    cptfVersion: 1,
    slug: config.slug,
    name: config.name,
    description: config.description,
    category: config.category,
    tags: config.tags ?? [],
    version: options.version ?? config.version ?? "1.0.0",
    author: options.author ?? { kind: "first_party" },
    runtime: {
      sdk: SDK_RANGE,
      externals: PLATFORM_EXTERNALS,
      ssr: options.ssr ?? true,
      viewport: "mobile-first",
    },
    theme: {
      tokens: config.theme,
      ...(config.themePresets ? { presets: config.themePresets } : {}),
    },
    fieldGroups: Object.entries(config.fieldGroups).map(([id, g]) => ({
      id,
      label: g.label,
      blockType: g.blockType,
      description: g.description,
      ...(g.optional !== undefined ? { optional: g.optional } : {}),
    })),
    fields: Object.entries(config.fields).map(([id, f]) => ({
      id,
      ...f,
    })),
    surfaces,
    // Lifted out of the rendered tree rather than declared separately, so the
    // <Layer> elements the author actually renders are exactly the ones the
    // editor can edit. `manifest.layers` is what the editor reads — leaving it
    // empty silently disables Level B and Level C editing for the template while
    // everything still LOOKS fine, so this is not optional.
    layers,
    capabilities: config.capabilities ?? [],
    migrations: config.migrations ?? [],
  };

  if (config.preview) {
    manifest.preview = {
      primaryScene: config.preview.primaryScene,
      scenes: config.preview.scenes ?? surfaces.map((s) => s.id),
    };
  } else if (surfaces.length > 0) {
    // A template with surfaces but no explicit preview config still needs a
    // primaryScene for the OG image (§7.2 step 4); defaulting beats failing the
    // build for something the author cannot reasonably be expected to repeat.
    manifest.preview = {
      primaryScene: surfaces[0].id,
      scenes: surfaces.map((s) => s.id),
    };
  }

  if (options.suggestedInr !== undefined) {
    manifest.pricing = { suggestedInr: options.suggestedInr };
  }

  if (config.pricingSuggestedInr !== undefined) {
    manifest.pricing = { suggestedInr: config.pricingSuggestedInr };
  }

  return { manifest, warnings };
}

/**
 * Canonical JSON for hashing. §3.4 + §5 step 7 (determinism).
 *
 * Keys are sorted recursively and there is no incidental whitespace, so the same
 * config always produces byte-identical manifest.json — which is what makes the
 * manifestHash check and the "same source in, same bytes out" hash verification
 * meaningful rather than theatre.
 */
export function canonicalJson(value: unknown): string {
  return JSON.stringify(sortKeys(value), null, 2) + "\n";
}

function sortKeys(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(sortKeys);
  if (value === null || typeof value !== "object") return value;
  const out: Record<string, unknown> = {};
  for (const key of Object.keys(value as Record<string, unknown>).sort()) {
    out[key] = sortKeys((value as Record<string, unknown>)[key]);
  }
  return out;
}
