/**
 * Collect <Layer> declarations from a rendered element tree, for the manifest.
 * docs/BLUEPRINT_TEMPLATE_PACKAGES.md §3.1 `layers`, §9 Levels B and C.
 *
 * WHY THIS EXISTS. Layers are declared inline in the author's JSX
 * (`<Layer id="title" default={...} customizable={...}>`) rather than in a
 * separate list, so that a layer the author actually renders is exactly the
 * layer the customer can edit — the same "one declaration" property that keeps
 * fields honest (§2.1a). But the MANIFEST is what the editor reads; it never
 * looks at the code. So the build has to lift those inline declarations out of
 * the tree and into `manifest.layers`.
 *
 * Without this step every template ships `layers: []`, and Level B (per-element
 * style) and Level C (freeform) editing are silently dead for the whole format —
 * the template renders correctly and nothing appears broken, which is precisely
 * why it needs a test rather than a glance.
 *
 * The walk is STRUCTURAL, not a React render: it calls `render()` once to get an
 * element tree and walks `props.children`. No hooks run, no DOM is needed, and a
 * component that would crash without content still yields its layers.
 */

import type { LayerCustomizable, LayerGeometry } from "./types";

export type CollectedLayer = {
  id: string;
  label: string;
  kind: "text" | "image" | "group" | "shape";
  surface: string;
  customizable?: LayerCustomizable;
  default: LayerGeometry;
};

type ElementLike = {
  type?: unknown;
  props?: Record<string, unknown> & { children?: unknown };
};

function isElement(value: unknown): value is ElementLike {
  return (
    typeof value === "object" &&
    value !== null &&
    "props" in (value as Record<string, unknown>)
  );
}

/** Identify SDK components by their function name, which survives bundling. */
function componentName(type: unknown): string {
  if (typeof type === "function") return type.name;
  if (typeof type === "string") return type;
  return "";
}

/**
 * Infer a layer's kind from what it contains, so authors do not have to repeat
 * themselves. `kind` drives which inspector controls the editor offers, so a
 * wrong guess is a cosmetic annoyance rather than a correctness problem —
 * defaulting to "group" is always safe.
 */
function inferKind(node: unknown): CollectedLayer["kind"] {
  let found: CollectedLayer["kind"] = "group";
  walk(node, (element) => {
    const name = componentName(element.type);
    if (name === "Text" || name === "RichText") {
      found = "text";
      return true;
    }
    if (name === "Img" || name === "Gallery") {
      found = "image";
      return true;
    }
    return false;
  });
  return found;
}

/** Depth-first walk. `visit` returning true stops the traversal. */
function walk(node: unknown, visit: (element: ElementLike) => boolean): boolean {
  if (Array.isArray(node)) {
    return node.some((child) => walk(child, visit));
  }
  if (!isElement(node)) return false;

  if (visit(node)) return true;

  return walk(node.props?.children, visit);
}

/**
 * Walk a rendered tree and collect every <Layer>, tagged with the <Surface> it
 * sits inside.
 *
 * A Layer outside any Surface is SKIPPED rather than collected with an empty
 * surface id: the manifest schema requires `layers[].surface` to resolve to a
 * declared surface, so emitting one would fail validation with a confusing
 * message. It is reported instead.
 */
export function collectLayers(tree: unknown): {
  layers: CollectedLayer[];
  warnings: string[];
} {
  const layers: CollectedLayer[] = [];
  const warnings: string[] = [];
  const seen = new Set<string>();

  const visit = (node: unknown, surfaceId: string | null): void => {
    if (Array.isArray(node)) {
      for (const child of node) visit(child, surfaceId);
      return;
    }
    if (!isElement(node)) return;

    const name = componentName(node.type);
    const props = node.props ?? {};

    if (name === "Surface") {
      const id = typeof props.id === "string" ? props.id : null;
      visit(props.children, id);
      return;
    }

    if (name === "Layer") {
      const id = typeof props.id === "string" ? props.id : "";
      if (!id) {
        warnings.push("a <Layer> is missing its id and was skipped");
      } else if (!surfaceId) {
        warnings.push(
          `<Layer id="${id}"> is not inside a <Surface> and was skipped; ` +
            "layers must live on a surface to be editable",
        );
      } else if (seen.has(id)) {
        warnings.push(`duplicate <Layer id="${id}"> — only the first is kept`);
      } else {
        seen.add(id);
        const geometry = (props.default ?? { x: 0, y: 0 }) as LayerGeometry;
        layers.push({
          id,
          // The id doubles as the label unless the author supplies one. Editor
          // labels are cosmetic; requiring a second string per layer would be
          // friction for no gain.
          label:
            typeof props.label === "string" && props.label
              ? props.label
              : humanise(id),
          kind: inferKind(props.children),
          surface: surfaceId,
          ...(props.customizable
            ? { customizable: props.customizable as LayerCustomizable }
            : {}),
          default: geometry,
        });
      }
      visit(props.children, surfaceId);
      return;
    }

    visit(props.children, surfaceId);
  };

  visit(tree, null);
  return { layers, warnings };
}

/** "opening.name" → "Opening name". */
function humanise(id: string): string {
  const text = id.replace(/[._-]+/g, " ").trim();
  return text.charAt(0).toUpperCase() + text.slice(1);
}
