/**
 * <Surface> and <Layer> — the Canva primitives. §2.1(b), §3.3, §9.
 *
 * The deal: the PLATFORM owns the transform, the AUTHOR owns the look. An author
 * writes <Layer id="title">…</Layer> and the SDK reads that layer's live geometry
 * from design state. Repositioning therefore works without the editor
 * understanding one line of the template's code.
 */

import type { CSSProperties, ReactNode } from "react";

import { SurfaceContext, useDesign, useSurfaceId, useTheme } from "./context";
import type { LayerCustomizable, LayerGeometry } from "./types";

/** "9:16" → 56.25 (percent), for the aspect-ratio padding box. */
function aspectToPercent(aspect: string): number {
  const [w, h] = aspect.split(":").map((n) => Number.parseFloat(n));
  if (!Number.isFinite(w) || !Number.isFinite(h) || w <= 0) return 100;
  return (h / w) * 100;
}

/**
 * A fixed-aspect stage. Geometry inside is PERCENTAGE-based, so the whole
 * surface scales uniformly to any screen width with zero JS (§3.3).
 *
 * That uniform %-scaling is how a Canva page renders on a phone, and it is what
 * makes mobile correct BY CONSTRUCTION rather than via a second hand-maintained
 * layout — the failure mode that makes the existing 24 expensive to change.
 */
export function Surface({
  id,
  aspect = "9:16",
  className,
  style,
  children,
}: {
  id: string;
  aspect?: string;
  className?: string;
  style?: CSSProperties;
  children?: ReactNode;
}) {
  const theme = useTheme();

  // Theme tokens become --cp-* custom properties here rather than on <html>, so
  // a template's colours are scoped to its own surface and cannot leak into the
  // host app (or, in the editor, into a second template rendered alongside).
  const themeVars: Record<string, string> = {};
  for (const [key, value] of Object.entries(theme)) {
    themeVars[`--cp-${key}`] = value;
  }

  return (
    <SurfaceContext.Provider value={id}>
      <div
        data-cp-surface={id}
        className={className}
        style={{
          position: "relative",
          width: "100%",
          // Padding-box aspect ratio rather than `aspect-ratio`, which needs a
          // fallback on older mobile Safari — the single most common browser for
          // these pages.
          paddingTop: `${aspectToPercent(aspect)}%`,
          overflow: "hidden",
          ...themeVars,
          ...style,
        } as CSSProperties}
      >
        <div
          style={{
            position: "absolute",
            inset: 0,
          }}
        >
          {children}
        </div>
      </div>
    </SurfaceContext.Provider>
  );
}

/**
 * A positionable element inside a Surface.
 *
 * `data-cp-layer` is the hit-testing contract (§9, "selection without
 * cooperation"): the editor overlay hit-tests the DOM and maps straight back to
 * a manifest entry, so the author writes NOTHING to enable selection.
 *
 * `customizable` is declared here for the CLI to lift into the manifest; the
 * runtime uses it only to know which overrides to honour. Anything absent is
 * locked, and the platform clamps ranges server-side on save (§3.3) so a crafted
 * payload cannot produce a 400px heading.
 */
export function Layer({
  id,
  default: defaultGeometry,
  customizable,
  className,
  style,
  children,
}: {
  id: string;
  default?: LayerGeometry;
  /** Read by the CLI at build time; inert at runtime. */
  customizable?: LayerCustomizable;
  className?: string;
  style?: CSSProperties;
  children?: ReactNode;
}) {
  const design = useDesign();
  const surfaceId = useSurfaceId();

  // Resolution order: freeform canvas geometry (Level C) beats a per-element
  // override (Level B) beats the author's default. One order, defined here, so
  // the editor preview and the published page can never disagree — a fork here
  // becomes "it looked different after I paid", the worst bug this system has
  // (§8.4).
  const canvasGeometry = surfaceId
    ? design.canvas?.[surfaceId]?.items?.[id]
    : undefined;
  const override = design.overrides?.[id];

  const geometry: LayerGeometry = {
    x: 0,
    y: 0,
    ...defaultGeometry,
    ...(override
      ? {
          ...(override.x !== undefined ? { x: override.x } : {}),
          ...(override.y !== undefined ? { y: override.y } : {}),
          ...(override.w !== undefined ? { w: override.w } : {}),
          ...(override.h !== undefined ? { h: override.h } : {}),
          ...(override.rot !== undefined ? { rot: override.rot } : {}),
          ...(override.z !== undefined ? { z: override.z } : {}),
        }
      : {}),
    ...(canvasGeometry ?? {}),
  };

  const styleOverride: CSSProperties = {};
  if (override?.color) styleOverride.color = override.color;
  if (override?.fontSize) styleOverride.fontSize = `${override.fontSize}em`;
  if (override?.align) styleOverride.textAlign = override.align;

  return (
    <div
      data-cp-layer={id}
      className={className}
      style={{
        position: "absolute",
        left: `${geometry.x}%`,
        top: `${geometry.y}%`,
        ...(geometry.w !== undefined ? { width: `${geometry.w}%` } : {}),
        ...(geometry.h !== undefined ? { height: `${geometry.h}%` } : {}),
        ...(geometry.rot ? { transform: `rotate(${geometry.rot}deg)` } : {}),
        ...(geometry.z !== undefined ? { zIndex: geometry.z } : {}),
        ...styleOverride,
        ...style,
      }}
    >
      {children}
    </div>
  );
}
