/**
 * Runtime context + hooks. docs/BLUEPRINT_TEMPLATE_PACKAGES.md §4.
 *
 * The platform mounts <TemplateRuntime> around the author's tree and passes
 * content/design/mode down. Authors never see this component — they only use the
 * hooks — but it is exported because the CLI's `dev` server and the platform's
 * PackageRenderer both need to mount it.
 *
 * WHY CONTEXT AND NOT PROPS. §2.1(b): the author writes <Layer id="title">, not
 * `style={{ position:'absolute', left:'12%' }}`. For that to work the SDK must
 * read live geometry from design state at any depth in the tree without the
 * author threading props through. Context is what makes repositioning work
 * "without the editor understanding one line of the template's code".
 */

import { createContext, useContext, type ReactNode } from "react";

import type { DesignState, TemplateMode } from "./types";

export type RuntimeValue = {
  content: Record<string, unknown>;
  design: DesignState;
  mode: TemplateMode;
  assets: (path: string) => string;
};

const EMPTY_DESIGN: DesignState = { theme: {}, overrides: {}, canvas: {} };

/**
 * Defaults rather than `undefined`, so a template rendered outside a provider
 * (a unit test, a Storybook-style harness) degrades to empty content instead of
 * throwing. A template that crashes when isolated is much harder to author.
 */
const RuntimeContext = createContext<RuntimeValue>({
  content: {},
  design: EMPTY_DESIGN,
  mode: "preview",
  assets: (path) => path,
});

export function TemplateRuntime({
  value,
  children,
}: {
  value: RuntimeValue;
  children: ReactNode;
}) {
  return (
    <RuntimeContext.Provider value={value}>{children}</RuntimeContext.Provider>
  );
}

export function useRuntime(): RuntimeValue {
  return useContext(RuntimeContext);
}

/**
 * Read a resolved content value.
 *
 * NEVER returns raw HTML (§4 table). `richtext` stays markdown-lite and is
 * rendered through <RichText>, which the platform sanitises — the existing
 * sanitizeRichText rules are unchanged and still forbid dangerouslySetInnerHTML
 * (§3.2, and §10.2 rejects that identifier outright at upload).
 */
export function useField<T = string>(id: string): T | undefined {
  const { content } = useRuntime();
  return content[id] as T | undefined;
}

/** Resolved theme tokens. Also injected as `--cp-*` CSS vars by <Surface>. */
export function useTheme(): Record<string, string> {
  return useRuntime().design.theme;
}

export function useDesign(): DesignState {
  return useRuntime().design;
}

/**
 * "edit" | "preview" | "published".
 *
 * Lets a template pause autoplay or skip an entrance animation in the editor,
 * where re-running a 3s intro on every keystroke makes the preview unusable.
 */
export function useMode(): TemplateMode {
  return useRuntime().mode;
}

/** Resolve a packaged asset path to its absolute CDN URL. */
export function useAsset(): (path: string) => string {
  return useRuntime().assets;
}

// ── Surface context ─────────────────────────────────────────────────────────
// A Layer needs to know which surface it sits in to look up its geometry, and
// requiring the author to repeat `surface="hero"` on every layer would be both
// noise and a chance to get it wrong. Layers read it from the enclosing Surface.

export const SurfaceContext = createContext<string | null>(null);

export function useSurfaceId(): string | null {
  return useContext(SurfaceContext);
}
